CREATE TABLE IF NOT EXISTS faqs(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,question VARCHAR(255) NOT NULL,answer TEXT NOT NULL,active TINYINT NOT NULL DEFAULT 1,sort_order INT NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX faq_order(active,sort_order)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS articles(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,slug VARCHAR(150) NOT NULL UNIQUE,title VARCHAR(190) NOT NULL,summary VARCHAR(400) NOT NULL DEFAULT '',body MEDIUMTEXT NOT NULL,cover_file VARCHAR(80) NULL,specialty_id INT UNSIGNED NULL,status VARCHAR(12) NOT NULL DEFAULT 'draft',published_at DATETIME NULL,author_admin_id BIGINT UNSIGNED NULL,views INT UNSIGNED NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NULL,INDEX article_public(status,published_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS site_pages(slug VARCHAR(40) PRIMARY KEY,title VARCHAR(190) NOT NULL,body MEDIUMTEXT NOT NULL,published TINYINT NOT NULL DEFAULT 0,updated_at DATETIME NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4
